# ft_list_size

Write a function that returns the number of elements in the linked list passed as parameter.

### Prototype & Structures
The `t_list` structure is defined in `ft_list.h`:
```c
typedef struct s_list {
    struct s_list *next;
    void          *data;
} t_list;

int ft_list_size(t_list *begin_list);
```

### Constraints
- Returns 0 if `begin_list` is NULL.
- Must compile cleanly with `-Wall -Wextra -Werror`.

extra_files.ft_list.h:
#ifndef FT_LIST_H
# define FT_LIST_H

typedef struct s_list {
	struct s_list *next;
	void          *data;
} t_list;

int ft_list_size(t_list *begin_list);

#endif

extra_files.test_list_size.c:
#include <assert.h>
#include <stdlib.h>
#include <stdio.h>
#include "ft_list.h"

int main(void)
{
	assert(ft_list_size(NULL) == 0);

	t_list c = { .next = NULL, .data = NULL };
	t_list b = { .next = &c,   .data = NULL };
	t_list a = { .next = &b,   .data = NULL };

	assert(ft_list_size(&c) == 1);
	assert(ft_list_size(&b) == 2);
	assert(ft_list_size(&a) == 3);

	printf("ALL TESTS PASSED: ft_list_size\n");
	return 0;
}

